# -*- coding: utf-8 -*-
# 第 10 批（A4）：營建工程空氣污染防制設施管理辦法（110/10/18）第1～20條
#                固定污染源逸散性粒狀污染物空氣污染防制設施管理辦法（112/7/6）第1～14條
CN = "ENV-03"; FD = "ENV-04"
Q = [
# ---------- 營建工程空氣污染防制設施管理辦法 ----------
(CN,"第1條",1,"營建空污-法源",
 "營建工程空氣污染防制設施管理辦法之訂定法源為何？",
 ["依空氣污染防制法第二十三條第二項規定訂定之","依空氣污染防制法第十六條第一項規定訂定之","依空氣污染防制法第三十二條第三項規定訂定","依空氣污染防制法第九十九條授權規定訂定"],"a",
 "第1條：本辦法依空氣污染防制法（以下簡稱本法）第二十三條第二項規定訂定之。本法第23條第1項要求公私場所應有效收集各種空氣污染物並維持防制設施正常運作，第2項則授權中央主管機關訂定收集設施、防制設施之規格、設置、操作、檢查、保養及記錄等辦法。固定污染源逸散性粒狀污染物之管理辦法亦依同一條項訂定。",
 "What is the legal basis of the Construction Site Air Pollution Control Facilities Regulations?",
 ["Article 23, paragraph 2 of the Air Pollution Control Act","Article 16, paragraph 1 of the Air Pollution Control Act","Article 32, paragraph 3 of the Air Pollution Control Act","Article 99 of the Air Pollution Control Act as delegated"],
 "Article 1; the same basis applies to the fugitive dust regulations."),

(CN,"第2條",3,"營建空污-圍籬定義",
 "本辦法所稱全阻隔式圍籬、半阻隔式圍籬及簡易圍籬之定義為何？",
 ["全阻隔式指全部使用非鏤空材料製作；半阻隔式指離地高度八十公分以上使用網狀鏤空材料，其餘使用非鏤空材料；簡易圍籬指至少離地高度八十公分以內使用非鏤空材料製作之拒馬或紐澤西護欄","全阻隔式指全部使用網狀鏤空材料製作；半阻隔式指離地高度一百二十公分以上使用非鏤空材料，其餘使用鏤空材料；簡易圍籬指至少離地高度一百公分以內使用鏤空材料製作之拒馬或護欄","全阻隔式指高度達三公尺以上之混凝土牆；半阻隔式指高度達二公尺以上之金屬圍籬；簡易圍籬指以塑膠布或防塵網懸掛於支架上形成之臨時性隔離設施，並得任意調整其高度","全阻隔式指設有防溢座及洗車設備之圍籬；半阻隔式指僅設防溢座而未設洗車設備之圍籬；簡易圍籬指未設防溢座亦未設洗車設備，僅以警示帶區隔工地範圍之設施"],"a",
 "第2條第2款至第4款：全阻隔式圍籬指全部使用非鏤空材料製作之圍籬；半阻隔式圍籬指離地高度八十公分以上使用網狀鏤空材料，其餘使用非鏤空材料製作之圍籬；簡易圍籬指以金屬、混凝土、塑膠等材料製作，至少離地高度八十公分以內使用非鏤空材料製作之拒馬或紐澤西護欄等實體隔離設施。第6條規定原則應設全阻隔式圍籬及防溢座，例外情形得設半阻隔式或簡易圍籬。",
 "How are fully enclosed, semi-enclosed and simple fences defined?",
 ["Fully enclosed uses non-perforated material throughout; semi-enclosed uses mesh above 80 cm from the ground and non-perforated below; simple means barriers or Jersey barriers with non-perforated material within at least 80 cm of the ground","Fully enclosed uses mesh material throughout; semi-enclosed uses non-perforated material above 120 cm from the ground and mesh below; simple means barriers or guardrails using perforated material within at least 100 cm of the ground","Fully enclosed means a concrete wall at least three metres high; semi-enclosed means a metal fence at least two metres high; simple means a temporary barrier of plastic sheeting or dust nets hung on frames whose height may be adjusted freely","Fully enclosed means a fence with an overflow sill and wheel washing; semi-enclosed means one with a sill but no wheel washing; simple means one with neither, where only warning tape marks off the extent of the construction site"],
 "Article 2, subparagraphs 2 to 4."),

(CN,"第2條",2,"營建空污-用詞定義",
 "本辦法所稱防溢座、粗級配、粒料及路面色差之定義為何？",
 ["防溢座指設於圍籬下方或洗車設備四周防止廢水溢流之設施；粗級配指舖設地面防止粉塵逸散之骨材；粒料指礫石碎石或其他防止粉塵逸散之粒狀物質；路面色差指道路表面因沙土附著造成與乾淨路面顏色差異","防溢座指設於工地出入口用以攔截車輛之設施；粗級配指粒徑二點五微米以下之細粒料；粒料指經篩選之砂土或黏土等填築材料；路面色差指道路因日照或雨水造成之自然色澤變化情形","防溢座指圍籬上方防止粉塵飛揚之擋板；粗級配指以水泥拌合之混凝土面層；粒料指噴灑於地面之化學穩定劑或乳膠劑；路面色差指路面因鋪設年限不同所產生之新舊顏色差異情形","防溢座指工地內之廢水收集坑及沉砂池；粗級配指鋪設於車行路徑之鋼板或瀝青混凝土；粒料指防塵布或防塵網等覆蓋材料；路面色差指經環保機關檢測超過粒狀物排放標準之情形"],"a",
 "第2條第5款、第8款至第10款：防溢座指設置於營建工地圍籬下方或洗車設備四周，防止廢水溢流之設施；粗級配指舖設地面，防止粉塵逸散之骨材；粒料指礫石、碎石或其他防止粉塵逸散之粒狀物質；路面色差指道路表面因沙土等粒狀污染物附著，造成與乾淨路面有顏色差異之情形。第10條規定洗車設施應有效清洗車體及輪胎，不得造成工地出入口及其延伸道路有路面色差。",
 "How are the overflow sill, coarse aggregate, aggregate and road colour difference defined?",
 ["The sill sits below the fence or around the wheel wash to stop wastewater overflow; coarse aggregate is bedding material stopping dust; aggregate is gravel, crushed stone or other dust-stopping granular material; colour difference is soil on the road making it differ from clean pavement","The sill sits at the site entrance to intercept vehicles; coarse aggregate means fine material 2.5 micrometres or less; aggregate means screened sand or clay used as fill; colour difference means the natural change in road colour caused by sunlight or by rainfall over time","The sill is a baffle atop the fence stopping dust from blowing; coarse aggregate means a concrete surface course mixed with cement; aggregate means chemical stabilizer or latex agent sprayed on the ground; colour difference means the contrast between newer and older pavement","The sill means the wastewater collection pit and settling basin on site; coarse aggregate means steel plate or asphalt concrete laid on haul routes; aggregate means dust cloth or dust netting used as cover; colour difference means exceeding the particulate emission standard on testing"],
 "Article 2, subparagraphs 5, 8, 9 and 10."),

(CN,"第3條",3,"營建空污-適用對象",
 "本辦法之適用對象及其排除規定為何？",
 ["適用應繳納空氣污染防制費業主之營建工程；但費額未達新臺幣二千元且施工面積未達一萬平方公尺、工期未達一年者，或依收費辦法得免繳費者，或其他經中央指定公告者，不在此限","適用所有領有建造執照之營建工程；但費額未達新臺幣二萬元且施工面積未達五千平方公尺、工期未達六個月者，或屬公共工程者，或經地方主管機關同意者，不在此限","適用施工面積達一萬平方公尺以上之營建工程；但屬道路、橋樑或管線工程者，或工期未滿三個月者，或位於一級防制區以外地區者，均不在本辦法之適用範圍","適用經環境影響評估審查通過之開發案；但屬政府興建之公共工程者，或已依水污染防治法取得排放許可者，或工程經費未達一億元者，不在此限"],"a",
 "第3條第1項：本辦法適用對象，指應依本法第16條第1項第1款規定繳納空氣污染防制費業主之營建工程；但下列營建工程不在此限：應申報繳納空氣污染防制費，其費額未達新臺幣二千元，且施工面積未達一萬平方公尺、工期未達一年者；依空氣污染防制費收費辦法規定得免繳納者；其他經中央主管機關指定公告者。施行細則第11條並定明營建業主之意義。",
 "Who is covered by these Regulations, and what is excluded?",
 ["Projects whose owners must pay the air pollution fee; excluded are projects with fees under NT$2,000 whose area is under 10,000 square metres and duration under a year, those exempt under the fee regulations, and others announced centrally","All projects holding a building permit; excluded are projects with fees under NT$20,000 whose area is under 5,000 square metres and duration under six months, public works projects, and any project the local authority agrees to exempt from them","Projects with a construction area of 10,000 square metres or more; excluded are road, bridge or pipeline works, works lasting under three months, and any works located outside a Class 1 air pollution control district","Development projects that have passed environmental impact review; excluded are public works built by government, projects holding a water discharge permit, and projects whose construction cost is under NT$100 million"],
 "Article 3, paragraph 1; see Enforcement Rules Article 11."),

(CN,"第3條",2,"營建空污-費額試算",
 "本辦法排除規定中所稱費額之試算，應以何者為基準？",
 ["以營建工程空氣污染防制費收費費率第三級費率為基準試算其費額","以營建工程空氣污染防制費收費費率第一級費率為基準試算其費額","以固定污染源空氣污染防制費之平均費率為基準試算其應繳費額","以工程總造價百分之零點五為基準推估其應繳納之空氣污染防制費"],"a",
 "第3條第2項：前項第一款費額之試算，以營建工程空氣污染防制費收費費率第三級費率為基準。第3條第1項第1款規定應申報繳納空氣污染防制費，其費額未達新臺幣二千元，且施工面積未達一萬平方公尺、工期未達一年者，不適用本辦法。",
 "Which rate is used to estimate the fee for the exclusion threshold?",
 ["The third-tier rate of the construction air pollution control fee schedule","The first-tier rate of the construction air pollution control fee schedule","The average rate of the stationary source air pollution control fee schedule","0.5 percent of the total construction cost is used to estimate the fee due"],
 "Article 3, paragraph 2."),

(CN,"第4條",2,"營建空污-工程分級",
 "本辦法所稱營建工程依施工規模如何分級？",
 ["分為第一級營建工程及第二級營建工程；第一級之工程類別及施工規模如附表一，第一級以外之營建工程屬第二級營建工程","分為甲級、乙級及丙級營建工程；各級之工程類別及施工規模均列於附表一，未列於附表者一律視為丙級營建工程","分為大型、中型及小型營建工程；依工程總造價分級，造價一億元以上為大型，一千萬元以上為中型，其餘為小型","分為公共工程及民間工程二類；公共工程一律適用較嚴之防制設施規定，民間工程則依施工面積另行分為三級"],"a",
 "第4條：本辦法所稱營建工程，依施工規模分為第一級營建工程及第二級營建工程；第一級營建工程之工程類別及施工規模如附表一，第一級以外之營建工程，屬第二級營建工程。第8條、第9條、第14條均就第一級營建工程訂有較嚴之防制設施要求，例如車行路徑及裸露區域防制設施須達百分之九十以上。",
 "How are construction projects graded by scale?",
 ["Into Class 1 and Class 2 projects; Class 1 types and scales appear in Appendix 1, and all other projects are Class 2 projects","Into Class A, B and C projects; all classes appear in Appendix 1, and any project not listed there is treated as a Class C project","Into large, medium and small projects by total cost; NT$100 million and above is large, NT$10 million and above medium, the rest small","Into public and private works; public works always face stricter control rules while private works are further graded by construction area"],
 "Article 4; stricter duties for Class 1 appear in Articles 8, 9 and 14."),

(CN,"第5條",2,"營建空污-標示牌",
 "營建業主於工程進行期間應設置之工地標示牌，其內容應載明哪些事項？",
 ["營建工程空氣污染防制費徵收管制編號、工地負責人姓名、電話及當地環保機關公害檢舉電話號碼","建造執照號碼、起造人與承造人名稱、監造建築師姓名及當地建管機關之工程查報專線電話號碼","工程名稱、開工與完工日期、工程總造價、承攬廠商統一編號及主辦機關之聯絡窗口姓名電話","空氣污染防制設施配置圖、每日灑水次數紀錄、裸露區域面積及當月空氣品質監測結果之數據"],"a",
 "第5條：營建業主於營建工程進行期間，應設置工地標示牌；標示牌內容應載明營建工程空氣污染防制費徵收管制編號、工地負責人姓名、電話及當地環保機關公害檢舉電話號碼。本法第94條並規定人民或團體得向直轄市、縣（市）主管機關檢舉違反本法規定之行為。",
 "What must the site notice board state?",
 ["The construction air pollution fee control number, the site manager's name and phone, and the local environmental agency complaint hotline","The building permit number, the names of the builder and contractor, the supervising architect's name, and the building agency's hotline","The project name, start and completion dates, total cost, the contractor's tax number, and the contact name and phone at the client agency","The layout of control facilities, the daily watering record, the area of exposed ground, and that month's air quality monitoring results"],
 "Article 5."),

(CN,"第6條",3,"營建空污-圍籬設置",
 "營建工地周界圍籬之設置規定為何？何種情形得設置半阻隔式或簡易圍籬？",
 ["原則應設定著地面之全阻隔式圍籬及防溢座，高度如附表二；道路轉角或轉彎處十公尺以內者得設半阻隔式圍籬；道路、隧道、管線或橋樑工程臨接道路寬度八公尺以下或工期未滿三個月者，得設連接之簡易圍籬","原則應設半阻隔式圍籬及防溢座，高度由營建業主自行決定；道路轉角或轉彎處二十公尺以內者得設全阻隔式圍籬；道路、隧道或橋樑工程臨接道路寬度十二公尺以下或工期未滿六個月者，得設簡易圍籬","原則應設簡易圍籬即可，防溢座則視需要設置；道路轉角或轉彎處五公尺以內者應設全阻隔式圍籬；工期未滿一年之各類營建工程，均得以防塵網或防塵布懸掛替代圍籬之設置","原則應設全阻隔式圍籬但免設防溢座，高度一律為二點四公尺；道路轉角或轉彎處三十公尺以內者得免設圍籬；工地周界臨接道路者，得以警示帶或交通錐替代圍籬並報請主管機關備查"],"a",
 "第6條：營建業主應於營建工地周界設置定著地面之全阻隔式圍籬及防溢座，圍籬高度規定如附表二；但道路轉角或轉彎處十公尺以內者，得設置半阻隔式圍籬。道路、隧道、管線或橋樑工程臨接道路寬度八公尺以下或施工工期未滿三個月者，得設置連接之簡易圍籬。前二項營建工程之工地周界臨接山坡地、河川或湖泊等天然屏障或其他具有與圍籬相同效果者，報請直轄市、縣（市）主管機關同意後，得免設置圍籬。",
 "What fencing must be installed at the site boundary, and when may lesser fencing be used?",
 ["A ground-fixed fully enclosed fence with an overflow sill, at the height in Appendix 2; a semi-enclosed fence is allowed within 10 metres of a road corner or bend; simple connected fencing is allowed for road, tunnel, pipeline or bridge works abutting a road 8 metres or narrower, or lasting under three months","A semi-enclosed fence with an overflow sill, at a height the owner decides; a fully enclosed fence is allowed within 20 metres of a road corner or bend; simple fencing is allowed for road, tunnel or bridge works abutting a road 12 metres or narrower, or works lasting under six months in total","Simple fencing suffices in principle with a sill installed as needed; a fully enclosed fence is required within 5 metres of a road corner or bend; for any project lasting under one year, hanging dust cloth or dust netting may be used in place of installing a fence at the boundary","A fully enclosed fence without a sill, always 2.4 metres in height; no fence at all is needed within 30 metres of a road corner or bend; where the site boundary abuts a road, warning tape or traffic cones may replace the fence if the authority is notified"],
 "Article 6, paragraphs 1 and 2."),

(CN,"第6條",2,"營建空污-免設圍籬",
 "營建工地在何種情形下，得報請主管機關同意後免設置圍籬？",
 ["工地周界臨接山坡地、河川或湖泊等天然屏障或其他具有與圍籬相同效果者，報請直轄市、縣（市）主管機關同意後得免設","工地位於一級防制區以外且施工工期未滿六個月者，報請直轄市、縣（市）主管機關備查後即得免設置圍籬及防溢座","工地已設置洗車台及自動灑水設備者，報請中央主管機關同意後得免設圍籬，但仍應設置防溢座及工地標示牌","工地屬政府興建之公共工程且已編列環境維護費用者，得逕行免設圍籬，無須報請任何主管機關同意或備查"],"a",
 "第6條第3項：營建工程之工地周界臨接山坡地、河川或湖泊等天然屏障或其他具有與圍籬相同效果者，報請直轄市、縣（市）主管機關同意後，得免設置圍籬。第19條另定營建業主未能依本辦法規定設置或採行防制設施、監測設施者，得提出同等防制效率或功能之替代方法，報請直轄市、縣（市）主管機關同意後為之。",
 "When may a site be exempted from installing a fence?",
 ["Where the boundary abuts natural barriers such as hillside, river or lake, or has an equivalent effect, subject to local authority consent","Where the site lies outside a Class 1 control district and works last under six months, after merely filing a notice with the local authority","Where a wheel wash and automatic sprinklers are installed, subject to central consent, though the sill and notice board are still needed","Where the works are government public works with an environmental budget, in which case no consent or filing of any kind is required"],
 "Article 6, paragraph 3; compare Article 19."),

(CN,"第7條",2,"營建空污-堆置物料",
 "營建工地堆置具粉塵逸散性之工程材料、砂石、土石方或廢棄物者，應採行何種防制設施？",
 ["應採行下列有效抑制粉塵防制設施之一：覆蓋防塵布、覆蓋防塵網或配合定期噴灑化學穩定劑","應同時採行覆蓋防塵布、覆蓋防塵網及噴灑化學穩定劑三種設施，缺一不可且應每日記錄備查","應一律堆置於封閉式建築物內，未設封閉式建築物者不得於營建工地內堆置任何具粉塵逸散性物料","應設置圍封式集氣系統將粒狀污染物收集處理後排放，並設置監測儀表連續記錄其集氣效率數據"],"a",
 "第7條：營建業主於營建工程進行期間，其所使用具粉塵逸散性之工程材料、砂石、土石方或廢棄物，且其堆置於營建工地者，應採行下列有效抑制粉塵之防制設施之一：一、覆蓋防塵布。二、覆蓋防塵網。三、配合定期噴灑化學穩定劑。固定污染源逸散性粒狀污染物空氣污染防制設施管理辦法第4條就公私場所之堆置行為則另有六款規定。",
 "What control must be used for dust-prone materials stockpiled on site?",
 ["One of the following: cover with dust cloth, cover with dust netting, or spray a chemical stabilizer on a regular basis","All three at once, dust cloth, dust netting and chemical stabilizer, with none omitted and a daily record kept for inspection","Stockpiling must always be inside an enclosed building, and without one no dust-prone material may be stockpiled at the site","An enclosure type gas collection system must capture and treat the particulates, with monitors continuously recording efficiency"],
 "Article 7; compare Article 4 of the fugitive dust regulations."),

(CN,"第8條",3,"營建空污-車行路徑",
 "營建工地內車行路徑應舖設何種防制設施？其面積比例要求為何？",
 ["應舖設鋼板、混凝土、瀝青混凝土或粗級配（粒料）之一；須達車行路徑面積百分之七十以上，屬第一級營建工程者須達百分之九十以上","應舖設鋼板、混凝土、瀝青混凝土或粗級配（粒料）之一；須達車行路徑面積百分之五十以上，屬第一級營建工程者須達百分之七十以上","應覆蓋防塵布或防塵網並配合灑水；須達車行路徑面積百分之八十以上，屬第一級營建工程者須達百分之一百","應設置自動灑水設備並每日灑水二次；須涵蓋車行路徑面積百分之六十以上，第一級營建工程者不另加嚴要求"],"a",
 "第8條：營建業主應於營建工地內之車行路徑，舖設鋼板、混凝土、瀝青混凝土、粗級配或粒料之一；前項防制設施須達車行路徑面積之百分之七十以上，屬第一級營建工程者，須達車行路徑面積之百分之九十以上；洗車設施至主要道路之車行路徑，亦應符合第一項之規定。",
 "What must be laid on haul routes inside the site, and to what extent?",
 ["Steel plate, concrete, asphalt concrete, or coarse aggregate or aggregate; covering at least 70 percent of the haul route, or 90 percent for Class 1 projects","Steel plate, concrete, asphalt concrete, or coarse aggregate or aggregate; covering at least 50 percent of the haul route, or 70 percent for Class 1 projects","Dust cloth or dust netting plus watering; covering at least 80 percent of the haul route area, and the full 100 percent where it is a Class 1 project","Automatic sprinklers watering twice a day; covering at least 60 percent of the haul route area, with no stricter requirement for Class 1 projects"],
 "Article 8."),

(CN,"第9條",3,"營建空污-裸露區域",
 "營建工地內裸露區域應採行之防制設施及其面積比例規定為何？",
 ["得採覆蓋防塵布網或稻草、舖設鋼板混凝土、舖設粗級配粒料、植生綠化、地表壓實配合每日灑水二次、噴灑化學穩定劑或設自動灑水設備之一；應達裸露區域面積百分之七十以上，第一級營建工程應達百分之九十以上","得採覆蓋防塵布網或稻草、舖設鋼板混凝土、舖設粗級配粒料、植生綠化或噴灑化學穩定劑之一；應達裸露區域面積百分之五十以上，第一級營建工程應達百分之八十以上，其餘部分免採行任何措施","應一律採行植生綠化並配合設置自動灑水設備，且須涵蓋裸露區域全部面積；第一級營建工程另應舖設鋼板或混凝土，第二級營建工程則得以覆蓋防塵網替代植生綠化之設施","應由營建業主自行選擇任一防制方式並報請主管機關核准；其面積比例由主管機關逐案核定，原則上不得低於裸露區域面積百分之三十，第一級營建工程不得低於百分之六十"],"a",
 "第9條第1項、第2項：營建業主應於營建工地內之裸露區域，採行下列有效抑制粉塵之防制設施之一：覆蓋防塵布、防塵網或稻草（蓆）；舖設鋼板、混凝土或瀝青混凝土；舖設粗級配或粒料；植生綠化；地表壓實且配合每日至少灑水二次並記錄用水量備查；配合定期噴灑化學穩定劑；設置自動灑水設備。防制設施應達裸露區域面積之百分之七十以上，屬第一級營建工程者應達百分之九十以上。",
 "What controls apply to exposed areas on site, and to what proportion?",
 ["Dust cloth, netting or straw cover; steel plate or concrete paving; coarse aggregate; planting; compaction with watering twice daily; chemical stabilizer; or automatic sprinklers; covering at least 70 percent of the exposed area, or 90 percent for Class 1 projects","Dust cloth, netting or straw cover; steel plate or concrete paving; coarse aggregate; planting; or chemical stabilizer; covering at least 50 percent of the exposed area, or 80 percent for Class 1 projects, with the remainder needing no measures at all","Planting must always be used together with automatic sprinklers over the entire exposed area; Class 1 projects must also lay steel plate or concrete, while Class 2 projects may substitute dust netting cover for the planting requirement","The owner may choose any method and seek the authority's approval; the proportion is fixed case by case but in principle not below 30 percent of the exposed area, and not below 60 percent where it is a Class 1 project"],
 "Article 9, paragraphs 1 and 2."),

(CN,"第9條",3,"營建空污-剩餘灑水",
 "裸露區域扣除已採行防制設施之剩餘部分，應如何處理？何種情形不適用？",
 ["剩餘部分須配合定期灑水，灑水頻率每日至少二次；於經濟部核定第三及第四階段停止及限制供水措施區域內之營建工程，不適用之","剩餘部分須配合定期灑水，灑水頻率每日至少四次；於經濟部核定第一及第二階段停止及限制供水措施區域內之營建工程，不適用之","剩餘部分應全部覆蓋防塵布或防塵網，不得以灑水替代；僅於颱風或豪雨警報期間得暫停覆蓋並報請主管機關備查","剩餘部分免採行任何防制措施亦免灑水，惟應於工地標示牌載明其面積並每月向主管機關申報一次備查"],"a",
 "第9條第2項、第3項：裸露區域扣除採行防制設施之剩餘部分，須配合定期灑水，灑水頻率每日至少二次；該剩餘部分須配合定期灑水之規定，於經濟部核定第三及第四階段停止及限制供水措施區域內之營建工程，不適用之。第16條之作業前灑水規定亦有相同之停限水區域排除適用規定。",
 "How must the remaining exposed area be handled, and when is that waived?",
 ["The remainder must be watered regularly at least twice a day; this is waived for sites in areas under stage three or four water restriction approved by MOEA","The remainder must be watered regularly at least four times a day; this is waived for sites in areas under stage one or two water restriction approved by MOEA","The remainder must be fully covered with dust cloth or netting and watering may not substitute; cover may pause only during typhoon or heavy rain warnings","The remainder needs no control measures or watering at all, though its area must be shown on the notice board and reported monthly to the authority"],
 "Article 9, paragraphs 2 and 3; compare Article 16."),

(CN,"第10條",3,"營建空污-洗車設施",
 "營建工地車行出入口洗車台之設置規定為何？",
 ["應設洗車台並符合四周設防溢座或其他防制設施、設置廢水收集坑、設置具有效沉砂作用之沉砂池；無設置空間時得以加壓沖洗設備清洗並妥善處理洗車廢水","應設洗車台並符合四周設圍籬、設置化學藥劑投藥設備、設置廢水回收再利用系統；無設置空間時得免清洗車輛，但應於出入口舖設鋼板並每日灑水","應設自動洗車設備並連續錄影存證，記錄保存六年；無設置空間時應報請中央主管機關核准後，改以人工清掃出入口延伸十公尺之路面替代","應由承包商於工地外設置共同洗車站供車輛使用；無共同洗車站者，得以防塵布覆蓋車輪替代清洗，並於出入口設置警示標誌"],"a",
 "第10條第1項、第2項：營建業主應於營建工地運送具粉塵逸散性之工程材料、砂石、土方或廢棄物之車行出入口，設置洗車台，且應符合下列規定：洗車台四周應設置防溢座或其他防制設施，防止洗車廢水溢出工地；設置廢水收集坑；設置具有效沉砂作用之沉砂池。營建工程無設置洗車台空間時，得以加壓沖洗設備清洗，並妥善處理洗車廢水。",
 "What are the requirements for a wheel washing bay at the site entrance?",
 ["A wash bay with an overflow sill or other controls around it, a wastewater collection pit, and an effective settling basin; where there is no space, pressurized washing may be used with proper wastewater handling","A wash bay surrounded by fencing, with chemical dosing equipment and a wastewater recycling system; where there is no space, vehicles need not be washed provided steel plate is laid and watered daily","An automatic wash system with continuous video kept for six years; where there is no space, central approval allows manual sweeping of the pavement extending ten metres from the entrance instead","A shared wash station set up outside the site by the contractor; where none exists, covering the wheels with dust cloth may substitute, with a warning sign posted at the site entrance"],
 "Article 10, paragraphs 1 and 2."),

(CN,"第10條",3,"營建空污-洗車效果",
 "洗車設施之清洗效果要求，以及區域開發、疏濬工程之額外規定為何？",
 ["車輛離開工地時應有效清洗車體及輪胎，表面不得附著污泥或造成工地出入口及其延伸道路有路面色差；屬區域開發工程、疏濬工程者，應洗掃鄰接道路並設置自動洗車設備","車輛離開工地時應以清水沖洗輪胎即可，車體表面得附著少量污泥；屬區域開發工程、疏濬工程者，得免設洗車台而以人工清掃鄰接道路方式替代其設置義務","車輛離開工地時應由工地負責人目視檢查並記錄；屬區域開發工程、疏濬工程者，應於工地內設置封閉式建築物存放車輛，並每日檢測周界粒狀物濃度","車輛離開工地時應於出入口停留十分鐘待污泥沉降；屬區域開發工程、疏濬工程者，應委託環境檢驗測定機構每月檢測鄰接道路之路面色差情形一次"],"a",
 "第10條第3項、第4項：第一項洗車設施於車輛離開營建工地時，應有效清洗車體及輪胎，其表面不得附著污泥，或造成工地出入口及其延伸之道路有路面色差；屬區域開發工程、疏濬工程者，應洗掃鄰接道路，並設置自動洗車設備，其項目及規格如附表三。第2條第10款並定義路面色差為道路表面因沙土等粒狀污染物附著造成與乾淨路面有顏色差異之情形。",
 "What washing result is required, and what extra duties apply to area development and dredging works?",
 ["Vehicles leaving must have body and tyres effectively washed with no mud attached and no road colour difference at the entrance or beyond; area development and dredging works must sweep and wash adjoining roads and install automatic wheel washing","Rinsing the tyres with water is enough when leaving and some mud may remain on the body; area development and dredging works may skip the wash bay entirely and sweep the adjoining roads by hand as a substitute for that duty","The site manager must visually check and record each departing vehicle; area development and dredging works must keep vehicles in an enclosed building on site and test boundary particulate concentrations on a daily basis","Vehicles leaving must wait ten minutes at the entrance for mud to settle; area development and dredging works must commission a testing organization to check the adjoining road for colour difference once every month"],
 "Article 10, paragraphs 3 and 4."),

(CN,"第11條",2,"營建空污-結構體",
 "營建工地結構體施工架外緣或結構體上，應設置何種可抑制粉塵之設施？",
 ["應設置防塵網、防塵布或自動灑水設備之一，其中自動灑水設備之灑水範圍應涵蓋結構體","應同時設置防塵網及防塵布，並另設加壓噴水設施於施工期間持續噴水不得間斷","應設置局部集氣系統將粒狀污染物收集處理後排放，並依規定設置監測儀表記錄之","應設置高度達二點四公尺之阻隔設施並包覆防塵布，其餘設施得由業主自行選擇採行"],"a",
 "第11條：營建業主於營建工程進行期間，應於營建工地結構體施工架外緣或結構體上設置下列可抑制粉塵之設施之一：一、防塵網。二、防塵布。三、自動灑水設備，灑水範圍應涵蓋結構體。第14條則就拆除期間規定應採行加壓噴水設施、結構體包覆防塵布或設置高度達二點四公尺阻隔設施之一。",
 "What dust suppression must be provided on the scaffolding or structure?",
 ["One of the following: dust netting, dust cloth, or automatic sprinklers whose spray covers the structure","Both dust netting and dust cloth, plus pressurized spraying kept running without pause during the works","A local gas collection system capturing and treating particulates, with monitors installed to record it","A 2.4 metre barrier wrapped in dust cloth, with any further facilities left to the owner's own choice"],
 "Article 11; compare Article 14 on demolition."),

(CN,"第12條",2,"營建空污-輸送方式",
 "營建工地內上層具粉塵逸散性物料輸送至地面或地下樓層，應採行何種方式？",
 ["應採以電梯孔道輸送、以建築物內部管道輸送、以密閉輸送管道輸送或以人工搬運之一；前三款管（孔）道出口應設置抑制粉塵逸散之圍籬並灑水","應採以吊車吊掛、以滑槽自由落下或以推車傾倒之一；出口處應設置防塵網並於作業期間持續噴水，作業後並應清掃地面粉塵","應一律採用密閉輸送管道並設置局部集氣系統，管道出口應接至袋式集塵器處理後排放，不得以人工搬運或電梯孔道輸送","應由營建業主報請主管機關核定其輸送方式；未經核定者，得逕以帆布覆蓋後自上層拋落至地面，並於落點四周灑水抑制粉塵"],"a",
 "第12條：營建業主將營建工地內上層具粉塵逸散性之工程材料、砂石、土方或廢棄物輸送至地面或地下樓層，應採行下列可抑制粉塵逸散之方式之一：一、以電梯孔道輸送。二、以建築物內部管道輸送。三、以密閉輸送管道輸送。四、以人工搬運。前項第一款至第三款管（孔）道出口，應設置抑制粉塵逸散之圍籬並灑水。",
 "How must dust-prone material be moved from upper floors to ground or basement levels?",
 ["By elevator shaft, internal building duct, sealed conveying duct, or manual carrying; for the first three, the duct outlet needs dust-suppressing fencing and watering","By crane hoisting, free fall down a chute, or tipping from a cart; the outlet needs dust netting and continuous spraying, with the ground swept after work","Always by sealed conveying duct with a local gas collection system discharging through a baghouse; manual carrying and elevator shafts are not permitted","By whatever method the authority approves for that owner; without approval, material may be dropped under a tarpaulin with watering around the landing point"],
 "Article 12."),

(CN,"第13條",3,"營建空污-運輸車輛",
 "運輸具粉塵逸散性物料之車輛，其貨廂覆蓋規定為何？",
 ["應使用密閉式貨廂，或以防塵布、防塵網緊密覆蓋貨廂並捆紮牢靠，邊緣應延伸覆蓋至貨廂上緣以下至少十五公分；並應具有防止載運物料滴落污水污泥之功能或設施","應使用密閉式貨廂，或以防塵布、防塵網覆蓋貨廂即可無須捆紮，邊緣應延伸覆蓋至貨廂上緣以下至少五公分；載運物料滴落污水者僅需事後清掃路面即可","應使用密閉式貨廂，不得以防塵布或防塵網覆蓋替代；貨廂並應設置自動灑水設備於行駛期間持續灑水，以避免載運物料於運輸途中逸散粉塵","應於貨廂上方加裝集氣罩並連接濾袋收集粉塵，覆蓋材料之邊緣應延伸至貨廂上緣以下至少三十公分，並應每趟次記錄其覆蓋情形備查"],"a",
 "第13條：營建業主於營建工程進行期間，運輸具粉塵逸散性之工程材料、砂石、土方或廢棄物之車輛應使用密閉式貨廂，或以防塵布、防塵網緊密覆蓋貨廂，並捆紮牢靠，邊緣應延伸覆蓋至貨廂上緣以下至少十五公分；運輸車輛貨廂應具有防止載運物料滴落污水、污泥之功能或設施。固定污染源逸散性粒狀污染物空氣污染防制設施管理辦法第6條第1款亦有相同之十五公分規定。",
 "How must the cargo bed of a hauling vehicle be covered?",
 ["Use a sealed cargo bed, or cover tightly with dust cloth or netting lashed securely, with the edge extending at least 15 cm below the top rim; the bed must also prevent dripping of wastewater or sludge","Use a sealed cargo bed, or simply lay dust cloth or netting over it without lashing, with the edge extending at least 5 cm below the top rim; dripping wastewater need only be swept from the road afterwards","Use a sealed cargo bed only, since dust cloth or netting may not substitute; the bed must also carry automatic sprinklers spraying continuously while driving to keep the load from giving off dust","Fit a collection hood over the bed connected to a filter bag; the covering edge must extend at least 30 cm below the top rim, and the covering must be recorded for every single trip made"],
 "Article 13; the same 15 cm rule appears in the fugitive dust regulations."),

(CN,"第14條",3,"營建空污-拆除工程",
 "營建工程進行拆除期間應採行之防制設施為何？第一級營建工程有何加嚴規定？",
 ["應採設置加壓噴水設施並於拆除期間持續噴水、於結構體包覆防塵布、於結構體四周設置高度達二．四公尺阻隔設施之一；屬第一級營建工程者應至少同時採行第一款及第二款","應採設置加壓噴水設施、於結構體包覆防塵網、於結構體四周設置高度達一．二公尺阻隔設施之一；屬第一級營建工程者應至少同時採行第二款及第三款之防制設施","應一律同時採行加壓噴水、包覆防塵布及設置阻隔設施三者，不分工程等級均應遵行；第一級營建工程另應設置局部集氣系統收集處理粒狀污染物","應由營建業主視現場狀況選擇適當方式並記錄備查；第一級營建工程應報請主管機關核定其拆除計畫後始得施工，第二級營建工程則免報核"],"a",
 "第14條：營建業主於營建工程進行拆除期間，應採行下列有效抑制粉塵之防制設施之一：一、設置加壓噴水設施，並於拆除作業期間持續噴水。二、於結構體包覆防塵布。三、於結構體四周設置高度達二．四公尺之阻隔設施。前項屬第一級營建工程者，應至少同時採行第一款、第二款之防制設施。第4條並定明第一級營建工程之工程類別及施工規模如附表一。",
 "What controls apply during demolition, and what extra duty falls on Class 1 projects?",
 ["One of the following: pressurized spraying kept running during demolition, wrapping the structure in dust cloth, or a 2.4 metre barrier around it; Class 1 projects must use at least the first two together","One of the following: pressurized spraying, wrapping the structure in dust netting, or a 1.2 metre barrier around it; Class 1 projects must use at least the second and third of these controls together","All three, pressurized spraying, dust cloth wrapping and a barrier, must always be used whatever the class of project; Class 1 projects must also add a local gas collection system","The owner may pick a suitable method for site conditions and keep a record; Class 1 projects need approval of a demolition plan before starting, while Class 2 projects need no approval"],
 "Article 14."),

(CN,"第15條",2,"營建空污-排氣井",
 "營建工地具有排放粒狀污染物質之排氣井或排風口者，應設置何種設備？",
 ["應設置旋風分離器、袋式集塵器或其他有效之集塵設備","應設置防塵網或防塵布覆蓋開口，並於作業期間持續灑水","應設置自動灑水設備涵蓋排氣井四周，並每日記錄用水量","應設置連續自動監測設施並與主管機關連線公開監測數據"],"a",
 "第15條：營建業主於營建工程進行期間，應於具有排放粒狀污染物質之排氣井或排風口，設置旋風分離器、袋式集塵器或其他有效之集塵設備。施行細則第16條第2項並列舉固定污染源之防制設備種類，包括集塵設備、脫硫設備、洗滌設備、吸收設備、集氣設備等。",
 "What equipment must be fitted to exhaust shafts or vents emitting particulates?",
 ["A cyclone separator, a baghouse dust collector, or other effective dust collection equipment","Dust netting or dust cloth over the opening, with continuous watering during the works","Automatic sprinklers covering the area around the shaft, with daily water use records kept","Continuous automatic monitoring linked to the authority with the data made public online"],
 "Article 15; compare Enforcement Rules Article 16(2)."),

(CN,"第16條",2,"營建空污-作業前灑水",
 "營建工程從事具粉塵逸散性之開挖、回填、搬運、裝卸、夯實或篩分作業前，應如何處理？",
 ["應灑水保持濕潤；該規定於經濟部核定第三及第四階段停止及限制供水措施區域內之營建工程，不適用之","應覆蓋防塵布並設置圍籬；該規定於經濟部核定第一及第二階段停止及限制供水措施區域內之工程不適用","應設置局部集氣系統收集處理；該規定於工期未滿三個月或施工面積未達一千平方公尺之工程不適用","應報請主管機關核准作業時段；該規定於政府興建之公共工程及緊急搶修工程不適用，得逕行施作"],"a",
 "第16條：營建業主於營建工程進行期間，從事具粉塵逸散性之開挖、回填、搬運、裝卸、夯實、篩分或其他易致粉塵逸散之作業前，應灑水保持濕潤；前項規定，於經濟部核定第三及第四階段停止及限制供水措施區域內之營建工程，不適用之。第9條第3項就裸露區域剩餘部分之定期灑水規定亦有相同之排除適用。",
 "What must be done before dust-prone excavation, backfilling, hauling or compaction?",
 ["Water the material to keep it moist; this is waived for sites in areas under stage three or four water restriction approved by MOEA","Cover with dust cloth and erect fencing; this is waived for sites in areas under stage one or two water restriction approved by MOEA","Install a local gas collection system to capture and treat dust; this is waived for works under three months or under 1,000 square metres","Obtain approval of the working hours from the authority; this is waived for government public works and for emergency repair works"],
 "Article 16; compare Article 9, paragraph 3."),

(CN,"第17條",2,"營建空污-破碎研磨",
 "營建工程從事破（粉）碎、研磨、切割、刨除等易致粉塵逸散之操作，應採行何種設施？",
 ["應設置局部集氣系統將粒狀污染物質收集及處理後排放，或設置加壓噴水設施並於操作期間持續噴水","應設置圍封式集氣系統並維持負壓操作，且其集氣效率應達百分之六十以上，並收集至污染防制設備","應覆蓋防塵布或防塵網並於操作前灑水一次，操作期間得視粉塵情形自行決定是否繼續灑水或加水","應於封閉式建築物內操作，未設封閉式建築物者不得從事破碎、研磨、切割或刨除等易致粉塵作業"],"a",
 "第17條：營建業主於營建工程進行期間，從事破（粉）碎、研磨、切割、刨除或其他易致粉塵逸散之操作，應設置或採行下列有效收集或抑制粉塵逸散設施之一：一、設置局部集氣系統，將粒狀污染物質收集及處理後排放。二、設置加壓噴水設施，並於操作期間持續噴水。固定污染源逸散性粒狀污染物空氣污染防制設施管理辦法第7條就製程操作則規定五款設施。",
 "What controls apply to crushing, grinding, cutting or planing operations?",
 ["Either a local gas collection system capturing and treating particulates before discharge, or pressurized spraying kept running during the operation","An enclosure type gas collection system kept under negative pressure with a collection efficiency of at least 60 percent routed to control equipment","Cover with dust cloth or netting and water once before starting, after which the operator may decide whether to keep watering as dust conditions require","Work only inside an enclosed building, since without one no crushing, grinding, cutting or planing operations may be carried out at the site at all"],
 "Article 17; compare Article 7 of the fugitive dust regulations."),

(CN,"第18條",3,"營建空污-監視系統",
 "營建工程施工規模達何種條件者，應設置監測儀表及攝錄影監視系統？其記錄保存期限為何？",
 ["工地面積達一萬平方公尺且工期達一年者，或外運土石體積（鬆方）達一萬立方公尺者；應設至少二支以上攝影鏡頭，記錄之影像及資料應保存一個月備查","工地面積達五千平方公尺且工期達六個月者，或外運土石體積（鬆方）達五千立方公尺者；應設至少一支攝影鏡頭，記錄之影像及資料應保存三個月備查","工地面積達二萬平方公尺或工期達二年者，或外運土石體積（鬆方）達五萬立方公尺者；應設至少四支以上攝影鏡頭，記錄之影像及資料應保存六個月備查","屬第一級營建工程者一律應設置，第二級營建工程則免設；應設至少二支以上攝影鏡頭，記錄之影像及資料應保存一年並定期上傳主管機關指定網站"],"a",
 "第18條：營建工程施工規模達下列條件之一者，營建業主應依附表四及附表五規定，設置空氣污染防制設施之監測儀表及攝錄影監視系統（至少須具備二支以上攝影鏡頭），並依表列項目及頻率進行記錄，記錄之影像及資料應保存一個月備查：一、工地面積達一萬平方公尺且工期達一年者。二、外運土石體積（鬆方）達一萬立方公尺者。固定污染源逸散性粒狀污染物管理辦法第11條亦規定影像保存一個月。",
 "Which project scales require monitoring instruments and video surveillance, and for how long are records kept?",
 ["A site of 10,000 square metres with works lasting a year, or 10,000 cubic metres of loose spoil hauled out; at least two cameras, with images and data kept for one month","A site of 5,000 square metres with works lasting six months, or 5,000 cubic metres of loose spoil hauled out; at least one camera, with images and data kept for three months","A site of 20,000 square metres or works lasting two years, or 50,000 cubic metres of loose spoil hauled out; at least four cameras, with images and data kept for six months","Every Class 1 project and no Class 2 project; at least two cameras, with images and data kept for one year and uploaded periodically to the authority's designated website"],
 "Article 18."),

(CN,"第19條",2,"營建空污-替代方法",
 "營建業主未能依本辦法規定設置或採行空氣污染防制設施、監測設施者，應如何處理？",
 ["得提出同等防制效率或功能之替代方法，報請直轄市、縣（市）主管機關同意後為之","得自行採行其認為適當之替代方法，於採行後三十日內報請主管機關備查即可","應報請中央主管機關核准後始得採行替代方法，地方主管機關無權同意其替代方案","不得採行任何替代方法，未能設置者應即停工至完成設置規定之防制設施後始得復工"],"a",
 "第19條：營建業主未能依本辦法規定設置或採行空氣污染防制設施、監測設施者，得提出同等防制效率或功能之替代方法，報請直轄市、縣（市）主管機關同意後為之。固定污染源逸散性粒狀污染物空氣污染防制設施管理辦法第12條亦有相同之替代方法規定，得報經直轄市、縣（市）主管機關同意後為之。",
 "What if the owner cannot install the required control or monitoring facilities?",
 ["An alternative of equal control efficiency or function may be proposed, subject to the consent of the municipal or county authority","The owner may adopt any alternative it considers suitable and merely file a notice with the authority within thirty days afterwards","Central approval must be obtained before any alternative may be used, since local authorities have no power to consent to one","No alternative is allowed at all; work must stop until the prescribed control facilities have been installed before it may resume"],
 "Article 19; compare Article 12 of the fugitive dust regulations."),

(CN,"第20條",1,"營建空污-施行日",
 "營建工程空氣污染防制設施管理辦法之施行日期為何？",
 ["本辦法自中華民國一百十一年十一月一日施行","本辦法自發布日施行，不另定其特別之施行日期","本辦法自發布後一年施行，以利營建業主調適","本辦法自中華民國一百十年十月十八日發布日施行"],"a",
 "第20條：本辦法自中華民國一百十一年十一月一日施行。本辦法修正日期為民國一百十年十月十八日，惟施行日期另定於一百十一年十一月一日，使營建業主有調整準備期間。固定污染源逸散性粒狀污染物空氣污染防制設施管理辦法第14條則規定除第7條第2項及第9條第3項自發布後三年施行外，自發布後一年施行。",
 "When did the Construction Site Air Pollution Control Facilities Regulations take effect?",
 ["On 1 November 2022 as separately provided in the Regulations","On the date of promulgation, with no separate effective date set","One year after promulgation, to let construction owners adjust","On 18 October 2021, the date on which they were promulgated"],
 "Article 20."),

# ---------- 固定污染源逸散性粒狀污染物空氣污染防制設施管理辦法 ----------
(FD,"第1條",1,"逸散粒狀-法源",
 "固定污染源逸散性粒狀污染物空氣污染防制設施管理辦法之訂定法源為何？",
 ["依空氣污染防制法第二十三條第二項規定訂定之","依空氣污染防制法第二十條第二項規定訂定之","依空氣污染防制法第三十二條第三項規定訂定","依空氣污染防制法第二十四條第四項規定訂定"],"a",
 "第1條：本辦法依空氣污染防制法（以下簡稱本法）第二十三條第二項規定訂定之。本法第23條第2項授權中央主管機關訂定固定污染源及其空氣污染物收集設施、防制設施或監測設施之規格、設置、操作、檢查、保養、記錄等辦法；營建工程空氣污染防制設施管理辦法亦依同一條項訂定。",
 "What is the legal basis of the fugitive particulate control facilities regulations?",
 ["Article 23, paragraph 2 of the Air Pollution Control Act","Article 20, paragraph 2 of the Air Pollution Control Act","Article 32, paragraph 3 of the Air Pollution Control Act","Article 24, paragraph 4 of the Air Pollution Control Act"],
 "Article 1."),

(FD,"第2條",3,"逸散粒狀-定義",
 "本辦法所稱逸散性粒狀污染物質、封閉式建築物及密閉式之定義為何？",
 ["逸散性粒狀污染物質指因人為或自然的破壞、擾動或風蝕作用致物質本身或其表面附著之粒狀物散布於空氣者；封閉式建築物指有外牆及屋頂包覆，除依法設置之通風口外其餘開口隨時保持關閉之建築物；密閉式指密閉污染源以阻隔粒狀污染物散布於空氣之方式","逸散性粒狀污染物質指經排放管道排放之粒狀污染物；封閉式建築物指四周設有圍籬及屋頂之臨時性構造物，其開口部得於作業期間保持開啟；密閉式指以防塵布或防塵網覆蓋物料表面達百分之八十以上之方式","逸散性粒狀污染物質指粒徑十微米以下之懸浮微粒；封閉式建築物指設有局部集氣系統之廠房，其通風口應維持正壓操作；密閉式指以圍籬或阻隔牆圍封堆置區四周，其總高度應達堆置高度一．二五倍之方式","逸散性粒狀污染物質指含有害空氣污染物之粒狀物；封閉式建築物指經主管機關核准並登載於操作許可證之建築物；密閉式指設置旋風分離器或袋式集塵器將粒狀污染物收集處理後排放之方式"],"a",
 "第2條第1款至第3款：逸散性粒狀污染物質指因人為或自然的破壞、擾動或風蝕作用，致物質本身或其表面附著之粒狀物散布於空氣者；封閉式建築物指有外牆及屋頂包覆之建築物，除依法設置之通風口外，其餘開口部分隨時保持關閉；密閉式指密閉污染源，以阻隔粒狀污染物散布於空氣之方式。第4條、第5條、第7條均以封閉式建築物內操作或密閉式作業作為可採行之防制設施之一。",
 "How are fugitive particulate matter, enclosed building and sealed defined?",
 ["Fugitive particulates are particles of a substance or attached to it that spread into the air through human or natural disturbance, damage or wind erosion; an enclosed building has walls and a roof with all openings but lawful vents kept closed; sealed means enclosing the source so particulates cannot spread","Fugitive particulates are particulates discharged through a stack; an enclosed building is a temporary structure with fencing and a roof whose openings may stay open during operations; sealed means covering at least 80 percent of the material surface with dust cloth or dust netting","Fugitive particulates are suspended particles of 10 micrometres or less; an enclosed building is a plant with a local gas collection system whose vents stay under positive pressure; sealed means enclosing a stockpile with walls at least 1.25 times the height of the pile itself","Fugitive particulates are particles containing hazardous air pollutants; an enclosed building is one approved by the authority and recorded in the operating permit; sealed means fitting a cyclone or baghouse to capture and treat particulates before they are discharged"],
 "Article 2, subparagraphs 1 to 3."),

(FD,"第2條",3,"逸散粒狀-集氣系統",
 "本辦法所稱圍封式集氣系統與局部集氣系統，其定義有何不同？",
 ["圍封式集氣系統以阻隔物包圍固定污染源使其與廠房其他空間隔絕，圍封空間應維持負壓操作使污染物完全收集至防制設備；局部集氣系統則藉由氣罩利用動力吸引收集製程設備逸散之粒狀污染物進防制設備","圍封式集氣系統藉由氣罩利用動力吸引收集粒狀污染物並維持正壓操作；局部集氣系統則以阻隔物包圍整座廠房使其與外界隔絕，並於出口設置旋風分離器及袋式集塵器處理後排放","圍封式集氣系統指以防塵網或阻隔牆圍封堆置區四周之設施；局部集氣系統則指於堆置區設置自動灑水設備並於堆置期間噴灑使堆置物保持濕潤之抑制粉塵設施","圍封式集氣系統指設於運輸車輛貨廂上方之密閉裝置；局部集氣系統則指設於公私場所出入口之加壓沖洗設備及自動洗車設備，用以清除車體及輪胎附著之粒狀物"],"a",
 "第2條第8款、第9款：圍封式集氣系統指以阻隔物包圍固定污染源，使其與廠房其他空間隔絕之集氣系統，該系統之圍封空間應維持負壓操作狀態，使固定污染源排放之粒狀污染物能完全收集至污染防制設備；局部集氣系統指藉由氣罩將製程設備逸散出之粒狀污染物，利用動力吸引、收集進防制設備之系統，系統應有效收集製程設備逸散之粒狀污染物。第7條規定製程操作得採行圍封式或局部集氣系統。",
 "How do an enclosure type and a local gas collection system differ?",
 ["The enclosure type surrounds the source with barriers to isolate it from the rest of the plant and keeps that space under negative pressure so all particulates reach the control equipment; the local type uses a hood and powered suction to draw process emissions into the equipment","The enclosure type uses a hood and powered suction while keeping positive pressure inside; the local type surrounds the whole plant with barriers to isolate it from outside and fits a cyclone and baghouse at the outlet to treat the air before it is discharged","The enclosure type means dust netting or barrier walls around a stockpile area; the local type means automatic sprinklers installed at the stockpile that spray during storage so that the stored material is kept moist and dust is suppressed","The enclosure type means a sealed device fitted above the cargo bed of a hauling vehicle; the local type means pressurized washing and automatic wheel washing at the premises entrance for cleaning particulates off bodies and tyres"],
 "Article 2, subparagraphs 8 and 9; see Article 7."),

(FD,"第3條",2,"逸散粒狀-適用對象",
 "本辦法之適用對象為何？何者不在適用範圍內？",
 ["指附表一所列會產生逸散性粒狀污染物之公私場所固定污染源；但不包括營建工地","指所有領有固定污染源操作許可證之公私場所；但不包括位於工業區內之污染源","指經中央主管機關指定公告應設置連續自動監測設施之固定污染源；但不包括礦區","指排放粒狀污染物超過排放標準之固定污染源；但不包括已繳納空氣污染防制費者"],"a",
 "第3條：本辦法適用對象，指附表一所列會產生逸散性粒狀污染物之公私場所固定污染源；但不包括營建工地。營建工地之空氣污染防制設施則適用營建工程空氣污染防制設施管理辦法。第6條第4款及第11條並就附表一所列特定序號之適用對象定有加嚴規定。",
 "Who is covered by these Regulations, and what is excluded?",
 ["Stationary sources at premises listed in Appendix 1 that generate fugitive particulates; construction sites are excluded","All premises holding a stationary source operating permit; sources located inside industrial parks are excluded","Sources designated as requiring continuous automatic monitoring by the central authority; mining areas are excluded","Sources whose particulate emissions exceed the standard; those that have paid the air pollution fee are excluded"],
 "Article 3; construction sites follow their own regulations."),

(FD,"第4條",3,"逸散粒狀-堆置設施",
 "公私場所堆置逸散性粒狀污染物質，應設置或採行之防制設施包括哪些？",
 ["堆置於封閉式建築物內；四周以防塵網或阻隔牆圍封且總高度達堆置高度一．二五倍以上；覆蓋防塵布網達堆置區面積百分之八十以上；噴灑化學穩定劑達百分之八十以上；設自動灑水設備；或其他經同意效果更優之設施","堆置於封閉式建築物內；四周以防塵網或阻隔牆圍封且總高度達堆置高度二倍以上；覆蓋防塵布網達堆置區面積百分之五十以上；噴灑化學穩定劑達百分之五十以上；設自動灑水設備；或其他經核准之設施","一律應堆置於封閉式建築物內並採密閉式輸送，未設封閉式建築物者不得堆置任何逸散性粒狀污染物質，亦不得以覆蓋、噴灑或灑水等方式替代其設置義務","應設置圍封式集氣系統並維持負壓操作，將粒狀污染物完全收集至防制設備；未能設置者得改以局部集氣系統，其集氣效率應達百分之六十以上並收集處理"],"a",
 "第4條第1項：公私場所堆置逸散性粒狀污染物質，應設置或採行下列有效抑制粒狀污染物逸散設施之一：堆置於封閉式建築物內；除出入口外堆置區四周應以防塵網或阻隔牆圍封，其總高度應達設計或實際堆置高度一．二五倍以上；覆蓋防塵布或防塵網，覆蓋面積應達堆置區面積百分之八十以上；噴灑化學穩定劑，噴灑面積應達百分之八十以上；設置自動灑水設備使堆置物保持濕潤；設置其他經直轄市、縣（市）主管機關同意效果優於前五款之設施。",
 "What controls may be used for stockpiling fugitive particulate material?",
 ["Storage inside an enclosed building; dust netting or barrier walls around it reaching 1.25 times the pile height; dust cloth or netting covering at least 80 percent of the area; chemical stabilizer over at least 80 percent; automatic sprinklers; or another facility agreed as better","Storage inside an enclosed building; dust netting or barrier walls around it reaching twice the pile height; dust cloth or netting covering at least 50 percent of the area; chemical stabilizer over at least 50 percent; automatic sprinklers; or another approved facility","Storage must always be inside an enclosed building with sealed conveying, and without such a building no fugitive particulate material may be stored, nor may covering, spraying or watering be used as a substitute for that duty","An enclosure type gas collection system under negative pressure must capture all particulates into control equipment; where impossible, a local system with at least 60 percent collection efficiency may be used to capture and treat them"],
 "Article 4, paragraph 1."),

(FD,"第4條",3,"逸散粒狀-加嚴規定",
 "堆置逸散性粒狀污染物質於三級防制區，或堆置規模達一定量者，有何加嚴規定？",
 ["採覆蓋或噴灑化學穩定劑而位於細懸浮微粒或懸浮微粒三級防制區者，覆蓋面積須達百分之九十以上；總設計或實際堆置體積達三千立方公尺以上或堆置量每年六萬公噸以上者，應採第一項第二款以外設施之一","採覆蓋或噴灑化學穩定劑而位於一級防制區者，覆蓋面積須達百分之一百；總設計或實際堆置體積達一千立方公尺以上或堆置量每年一萬公噸以上者，應一律堆置於封閉式建築物內不得例外","採覆蓋或噴灑化學穩定劑而位於總量管制區者，覆蓋面積須達百分之八十五以上；總設計或實際堆置體積達五千立方公尺以上者，應設置圍封式集氣系統並維持其負壓操作狀態","採覆蓋或噴灑化學穩定劑者不分區位，覆蓋面積一律為百分之八十；堆置規模無論大小均得自由選擇第一項各款設施之一，主管機關不得另為加嚴之要求或限制"],"a",
 "第4條第2項、第3項：公私場所採第1項第2款至第5款之設施，除出入口外應設置阻隔設備及防溢座，防止堆置物掉落或溢流至堆置區外；採第3款或第4款之設施，位於細懸浮微粒或懸浮微粒三級防制區者，覆蓋面積須達堆置區面積百分之九十以上。逸散性粒狀污染物質堆置場，總設計或實際堆置體積在三千立方公尺以上或堆置量在每年六萬公噸以上者，應採行第1項第2款以外設施之一。第13條並規定堆置物質處理後不易散布者，得不受第4條限制。",
 "What stricter rules apply in Class 3 districts or at large stockpiles?",
 ["Where covering or stabilizer is used in a Class 3 district for PM2.5 or PM10, coverage must reach 90 percent; stockyards of 3,000 cubic metres or 60,000 tonnes a year must use a facility other than subparagraph 2","Where covering or stabilizer is used in a Class 1 district, coverage must reach 100 percent; stockyards of 1,000 cubic metres or 10,000 tonnes a year must always be housed inside an enclosed building with no exception","Where covering or stabilizer is used in a total quantity control zone, coverage must reach 85 percent; stockyards of 5,000 cubic metres or more must install an enclosure type collection system kept under negative pressure","Coverage is always 80 percent wherever the site lies; whatever the size of the stockpile any of the listed facilities may be freely chosen, and the authority may impose no stricter requirement or limit at all"],
 "Article 4, paragraphs 2 and 3; compare Article 13."),

(FD,"第5條",2,"逸散粒狀-輸送",
 "公私場所輸送逸散性粒狀污染物質，應設置或採行何種設施？何種情形不在此限？",
 ["應於封閉式建築物內操作、採用密閉式輸送系統，或於輸送系統出入口接駁點及有逸散之虞處採用局部集氣系統或自動灑水設施之一；但採濕式輸送作業者不在此限","應同時採用封閉式建築物、密閉式輸送系統及局部集氣系統三者，缺一不可；但屬礦區或堆置區之輸送作業者，得僅採其中之一並報請主管機關同意","應一律採用密閉式輸送系統並設置圍封式集氣系統維持負壓；但輸送距離未達五十公尺或每日輸送量未達一百公噸者，得改以人工搬運方式替代","應於輸送路徑舖設混凝土或鋼板並保持濕潤，且不得有路面色差；但位於封閉式建築物內之輸送作業者，得免舖設亦免保持路面濕潤"],"a",
 "第5條：公私場所輸送逸散性粒狀污染物質，應設置或採行下列有效收集或抑制粒狀污染物逸散設施之一，但採濕式輸送作業者不在此限：一、於封閉式建築物內操作。二、採用密閉式輸送系統。三、輸送系統出入口、接駁點及其他有粒狀污染物逸散之虞處，應採用局部集氣系統或自動灑水設施。第7條就製程、操作或裝卸作業另定五款防制設施，亦以採濕式製程作業者為除外。",
 "What controls apply to conveying fugitive particulate material, and what is excluded?",
 ["One of: operating inside an enclosed building, using a sealed conveying system, or fitting local gas collection or automatic sprinklers at inlets, transfer points and other leak-prone spots; wet conveying is excluded","All three at once, the enclosed building, the sealed conveying system and local gas collection, with none omitted; only mining areas or stockyards may use one of them with the authority's consent","A sealed conveying system with an enclosure type collection system under negative pressure is always required; where the distance is under 50 metres or under 100 tonnes a day, manual carrying may be used","The conveying route must be paved with concrete or steel plate and kept moist with no road colour difference; conveying inside an enclosed building need not be paved or kept moist at all"],
 "Article 5; compare Article 7."),

(FD,"第6條",3,"逸散粒狀-車輛運輸",
 "公私場所以車輛運輸逸散性粒狀污染物質，其貨廂及廠內路徑之規定為何？",
 ["車輛應使用密閉式貨廂或以封蓋緊密覆蓋，採防塵布網者應捆紮牢靠且邊緣延伸至貨箱上緣以下至少十五公分；廠內通行路徑及區域應舖設混凝土、瀝青混凝土或鋼板且不得有路面色差","車輛應使用密閉式貨廂或以封蓋覆蓋即可無須捆紮，採防塵布網者邊緣延伸至貨箱上緣以下至少五公分；廠內通行路徑及區域應舖設粗級配或粒料並得有輕微路面色差","車輛得以敞篷貨廂載運但應降低車速行駛，並於出廠前灑水濕潤載運物料；廠內通行路徑及區域應每日清掃二次，舖面材質則由公私場所自行決定不受限制","車輛應加裝集氣罩並連接袋式集塵器收集粉塵；廠內通行路徑及區域應設置自動灑水設備連續灑水，並依規定設置監測儀表記錄其用水量及灑水頻率"],"a",
 "第6條第1款、第2款：運輸逸散性粒狀污染物質之車輛應使用密閉式貨廂，或以封蓋緊密覆蓋貨廂，封蓋採防塵布或防塵網者應捆紮牢靠，邊緣應延伸覆蓋至貨箱上緣以下至少十五公分，貨廂並應具有防止載運物料滴落污水、污泥之功能或設施；公私場所內供運輸車輛通行之路徑及區域，應舖設混凝土、瀝青混凝土或鋼板，且不得有路面色差，但位於堆置區及礦區者，得舖設粗級配或粒料並於作業期間灑水保持濕潤。",
 "What rules apply to hauling vehicles and in-plant routes?",
 ["Sealed cargo beds or tightly fitted covers, with dust cloth or netting lashed securely and extending at least 15 cm below the top rim; in-plant routes must be paved with concrete, asphalt concrete or steel plate with no road colour difference","Sealed cargo beds or covers laid on without lashing, with dust cloth or netting extending at least 5 cm below the top rim; in-plant routes must be laid with coarse aggregate or aggregate and slight road colour difference is tolerated","Open cargo beds are allowed if the vehicle drives slowly and the load is watered before leaving; in-plant routes must be swept twice a day while the surfacing material is left entirely to the premises to decide","Vehicles must carry a collection hood ducted to a baghouse; in-plant routes must have automatic sprinklers running continuously with monitors recording the water used and the frequency of spraying"],
 "Article 6, subparagraphs 1 and 2."),

(FD,"第6條",3,"逸散粒狀-洗車與洗掃",
 "運輸車輛離開公私場所前之清洗規定，以及附表一序號一至六適用對象之加嚴規定為何？",
 ["離開前應以加壓沖洗設備清洗車體及輪胎，表面不得附著逸散性粒狀污染物質，門口及其延伸十公尺之路面不得有帶出之污染物；序號一至六者應洗掃出入口鄰接道路並設置自動洗車設備","離開前應以人工清掃車體及輪胎，表面得附著少量粒狀污染物質，門口及其延伸三公尺之路面不得有帶出之污染物；序號一至六者僅需洗掃出入口鄰接道路而免設自動洗車設備","離開前應停留於出入口十分鐘待粒狀物沉降，門口及其延伸二十公尺之路面應每日灑水二次；序號一至六者應設置攝錄影監視系統連續錄影並保存六個月備查","離開前應由公私場所人員目視檢查並作成紀錄，門口路面色差得於發現後三日內清除；序號一至六者應設置圍封式集氣系統於出入口收集粒狀污染物並處理後排放"],"a",
 "第6條第3款、第4款：運輸車輛離開公私場所前，應以加壓沖洗設備清洗車體及輪胎，其表面不得附著逸散性粒狀污染物質；公私場所門口及其延伸十公尺之路面，不得有運輸車輛帶出之逸散性粒狀污染物質。附表一所列序號一至六之適用對象，應洗掃其運輸車輛出入口之鄰接道路，並設置自動洗車設備，其規格如附表二；但堆置於封閉式建築物內且採密閉式輸送並報經直轄市、縣（市）主管機關同意者，不在此限。",
 "What washing is required before vehicles leave, and what extra duty falls on Appendix 1 items 1 to 6?",
 ["Wash the body and tyres with pressurized equipment leaving no material attached, and keep the gate and 10 metres of pavement beyond free of carried-out material; items 1 to 6 must sweep and wash the adjoining road and install automatic wheel washing","Sweep the body and tyres by hand with a little material allowed to remain, and keep the gate and 3 metres of pavement beyond free of carried-out material; items 1 to 6 need only sweep the adjoining road without installing automatic wheel washing","Wait ten minutes at the gate for particulates to settle, and water the gate and 20 metres of pavement beyond twice each day; items 1 to 6 must install video surveillance recording continuously with the footage kept for six months","Have staff inspect each vehicle visually and record it, with any road colour difference at the gate cleared within three days; items 1 to 6 must install an enclosure type collection system at the gate to capture and treat particulates"],
 "Article 6, subparagraphs 3 and 4."),

(FD,"第7條",3,"逸散粒狀-製程操作",
 "公私場所從事易致粒狀污染物逸散之製程、操作或裝卸作業，應採行何種設施？有何除外及加嚴規定？",
 ["應採設置圍封式集氣系統、設置局部集氣系統、採用密閉式作業、於封閉式建築物內操作或於作業期間灑水保持濕潤之一；採濕式製程作業者不在此限；附表一序號四及十五採局部集氣系統者，集氣效率應達百分之六十以上","應採設置圍封式集氣系統、設置局部集氣系統或採用密閉式作業之一；採乾式製程作業者不在此限；附表一序號四及十五採局部集氣系統者，集氣效率應達百分之九十以上並每月檢測一次","應同時設置圍封式集氣系統及局部集氣系統，並於封閉式建築物內操作；無任何除外規定，附表一所列全部適用對象之集氣效率均應達百分之八十以上並連續監測記錄","應由公私場所自行選擇適當方式並報請主管機關備查；採濕式製程作業者仍應設置集氣系統，附表一序號四及十五者得免設任何集氣系統但應每日灑水四次"],"a",
 "第7條：公私場所從事易致粒狀污染物逸散之製程、操作或裝卸作業，應設置或採行下列有效收集或抑制粒狀污染物逸散之設施之一，但採濕式製程作業者不在此限：一、設置圍封式集氣系統。二、設置局部集氣系統。三、採用密閉式作業。四、於封閉式建築物內操作。五、於作業期間灑水，使物料保持濕潤。附表一所列序號四及十五之適用對象，採行前項第二款防制設施者，其集氣效率應達百分之六十以上，並收集至污染防制設備。第14條並規定第7條第2項自發布後三年施行。",
 "What controls apply to dust-prone processes, and what exclusions or stricter rules exist?",
 ["One of: an enclosure type collection system, a local collection system, sealed operation, operating inside an enclosed building, or watering to keep material moist; wet processes are excluded; Appendix 1 items 4 and 15 using a local system need at least 60 percent collection efficiency","One of: an enclosure type collection system, a local collection system, or sealed operation; dry processes are excluded; Appendix 1 items 4 and 15 using a local system need at least 90 percent collection efficiency tested once every month","Both an enclosure type and a local collection system are required together with operating inside an enclosed building; nothing is excluded, and every listed target needs at least 80 percent efficiency monitored and recorded continuously","The premises may pick a suitable method and file it with the authority; wet processes must still install a collection system, while items 4 and 15 need no system at all provided they water the material four times a day"],
 "Article 7; the second paragraph takes effect three years after promulgation."),

(FD,"第8條",2,"逸散粒狀-裸露區域",
 "公私場所管理之裸露區域應設置或採行何種設施？何種情形不在此限？",
 ["應採植生綠化、覆蓋稻草蓆或碎木、舖設混凝土或瀝青混凝土、覆蓋防塵布網、舖設粗級配粒料並保持濕潤、噴灑化學穩定劑或灑水並保持濕潤之一；但地面表土硬化不易引起揚塵並報經地方主管機關同意者不在此限","應採植生綠化或舖設混凝土之一，其餘覆蓋、噴灑或灑水方式均不得採行；但屬礦區、堆置區或位於封閉式建築物內之裸露區域，得免採行任何防制設施亦無須報請主管機關同意","應一律覆蓋防塵布或防塵網並達裸露區域面積百分之九十以上；但經環境檢驗測定機構檢測周界粒狀物濃度符合空氣品質標準並報請中央主管機關核准者，得免予覆蓋","應設置自動灑水設備涵蓋全部裸露區域並每日灑水四次；但位於經濟部核定停止及限制供水措施區域內者，得改以覆蓋防塵布方式替代並報請主管機關備查"],"a",
 "第8條：公私場所管理之裸露區域，應於裸露區域設置或採行下列有效抑制粒狀污染物逸散之設施之一，但地面表土硬化，不易引起揚塵，並報經直轄市、縣（市）主管機關同意者，不在此限：一、植生綠化。二、覆蓋稻草蓆或碎木。三、舖設混凝土或瀝青混凝土。四、覆蓋防塵布或防塵網。五、舖設粗級配或粒料，並保持濕潤。六、噴灑化學穩定劑。七、灑水並保持濕潤。第9條第2項並規定道路交通島及人行道之裸露區域應採行本條第一款至第五款設施之一。",
 "What controls apply to exposed areas, and when are they waived?",
 ["One of: planting, straw mat or wood chip cover, concrete or asphalt paving, dust cloth or netting cover, coarse aggregate kept moist, chemical stabilizer, or watering to keep moist; waived where hardened topsoil raises little dust with local consent","Only planting or concrete paving may be used, since covering, spraying or watering are not allowed; exposed areas in mining zones, stockyards or enclosed buildings need no controls at all and no consent from the authority","Dust cloth or netting must always cover at least 90 percent of the exposed area; covering may be omitted where a testing organization finds boundary levels meeting the air quality standard and the central authority approves","Automatic sprinklers must cover the whole exposed area and run four times a day; in areas under water restriction approved by MOEA, dust cloth cover may be substituted with a notice filed with the authority"],
 "Article 8; compare Article 9, paragraph 2."),

(FD,"第9條",3,"逸散粒狀-道路管理",
 "公私場所對其所管理之道路及交通島、人行道，有何維護規定？",
 ["道路不得有破損或髒污致路面色差或逸散粒狀污染物；交通島及人行道之裸露區域應採第八條第一款至第五款設施之一，其覆土高度不得超過緣石上緣","道路得有輕微破損但不得有路面色差；交通島及人行道之裸露區域應一律舖設混凝土，其覆土高度不得超過緣石上緣二十公分並每月檢查一次","道路應每日洗掃二次並記錄用水量；交通島及人行道之裸露區域應設置自動灑水設備，其覆土高度得高於緣石上緣但不得超過三十公分","道路維護由地方主管機關負責，公私場所僅需負擔費用；交通島及人行道之裸露區域應覆蓋防塵網，其覆土高度由公私場所視綠化需要自行決定"],"a",
 "第9條：公私場所應維護其所管理之道路，不得有破損或髒污致路面色差，或逸散粒狀污染物於空氣中；前項道路如設有交通島及人行道，其裸露區域應設置或採行第8條第1款至第5款所定設施之一；前項道路之交通島及人行道，其裸露區域覆土高度不得超過緣石上緣，但採行其他有效減少廢水溢流污染路面之設施並報經直轄市、縣（市）主管機關同意者，不在此限。第14條規定第9條第3項自發布後三年施行。",
 "What must premises do about roads, traffic islands and sidewalks they manage?",
 ["Roads must not be damaged or soiled so as to cause colour difference or release particulates; exposed areas on islands and sidewalks need one of Article 8's first five controls, with soil no higher than the kerb top","Roads may be slightly damaged but must show no colour difference; exposed areas on islands and sidewalks must always be concreted, with soil no more than 20 cm above the kerb and inspected monthly","Roads must be swept and washed twice daily with water use recorded; exposed areas on islands and sidewalks need automatic sprinklers, and soil may rise above the kerb but not by more than 30 cm","Road upkeep falls to the local authority with the premises only paying; exposed areas on islands and sidewalks need dust netting, and soil height is decided by the premises as its planting requires"],
 "Article 9; paragraph 3 takes effect three years after promulgation."),

(FD,"第10條",3,"逸散粒狀-監測紀錄",
 "公私場所設置灑水設備、洗車設備或採行圍封式、局部集氣系統等防制設施者，其監測及紀錄義務為何？",
 ["應依附表三規定設置監測儀表，並依該表所列項目及頻率進行記錄；空氣污染防制設施操作運轉紀錄應保存六年，以備查閱","應依附表三規定設置監測儀表，並依該表所列項目及頻率進行記錄；空氣污染防制設施操作運轉紀錄應保存一個月，以備查閱","應設置連續自動監測設施並與直轄市、縣（市）主管機關連線公開於網站；操作運轉紀錄應保存三年，並每季向主管機關申報一次","應委託環境檢驗測定機構每半年檢測一次防制設施效能；檢測報告應保存十年，並於檢測後三十日內報請中央主管機關備查"],"a",
 "第10條：公私場所設置灑水設備、洗車設備或採行噴灑化學穩定劑、圍封式或局部集氣系統等空氣污染防制設施者，應依附表三規定設置監測儀表，並依該表所列項目及頻率進行記錄；前項空氣污染防制設施操作運轉紀錄應保存六年，以備查閱。第11條所定攝錄影監視系統之影像及資料則僅須保存一個月。",
 "What monitoring and record duties apply to sprinklers, wheel washes and collection systems?",
 ["Install monitoring instruments per Appendix 3 and record the listed items at the listed frequency; operating records must be kept for six years for inspection","Install monitoring instruments per Appendix 3 and record the listed items at the listed frequency; operating records must be kept for one month for inspection","Install continuous automatic monitoring linked to the local authority and published online; operating records must be kept three years and reported quarterly","Commission a testing organization to test control performance every six months; reports must be kept ten years and filed centrally within thirty days of testing"],
 "Article 10; compare the one-month video retention in Article 11."),

(FD,"第11條",3,"逸散粒狀-攝錄影系統",
 "附表一所列序號一至七之適用對象，其攝錄影監視系統之設置、保存及故障處理規定為何？",
 ["應設置至少二支以上攝影鏡頭並依表列項目及頻率記錄，影像及資料保存一個月；故障時應即時通報地方主管機關並於七日內完成修復，無法完成者應報經核准並於核准期限內完成","應設置至少一支攝影鏡頭並依表列項目及頻率記錄，影像及資料保存六個月；故障時應於三十日內完成修復，無須通報主管機關亦無須申請展延其修復期限","應設置至少四支以上攝影鏡頭並連線至中央主管機關，影像及資料保存六年；故障時應立即停止相關作業，至修復完成並經主管機關查驗合格後始得恢復","應設置至少二支以上攝影鏡頭並公開於網站供民眾查詢，影像及資料保存一年；故障時應於二十四小時內完成修復，逾期即視為未設置攝錄影監視系統"],"a",
 "第11條：附表一所列序號一至七之適用對象，應依附表四規定，設置攝錄影監視系統（至少須具備二支以上攝影鏡頭），並依表列項目及頻率進行記錄，記錄之影像及資料應保存一個月，以備查閱；攝錄影監視系統故障時，應即時通報直轄市、縣（市）主管機關，並於七日內完成修復，如無法於七日內完成修復，應報經直轄市、縣（市）主管機關核准，並於核准期限內完成修復。第13條並規定堆置物質處理後不易散布並經同意者，不受第11條規定限制。",
 "What rules govern video surveillance for Appendix 1 items 1 to 7?",
 ["At least two cameras recording the listed items at the listed frequency, with images kept one month; failures must be reported at once and repaired within seven days, or within an approved extension","At least one camera recording the listed items at the listed frequency, with images kept six months; failures must be repaired within thirty days with no report to the authority and no extension needed","At least four cameras linked to the central authority, with images kept six years; on failure operations must stop until repair is complete and the authority has inspected and cleared the system","At least two cameras published online for public viewing, with images kept one year; failures must be repaired within twenty-four hours or the system counts as never having been installed"],
 "Article 11; compare Article 13."),

(FD,"第12條",2,"逸散粒狀-替代方法",
 "公私場所未能依本辦法設置或採行防制設施、監測儀表或攝錄影監視系統者，應如何處理？",
 ["得提出替代之方法，報經直轄市、縣（市）主管機關同意後為之","得自行採行替代方法並作成紀錄留存備查，無須報請主管機關同意","應報請中央主管機關核准後始得採行替代方法，地方機關無此權限","不得提出替代方法，應立即停止相關作業至完成設置規定設施為止"],"a",
 "第12條：公私場所未能依本辦法設置或採行空氣污染防制設施、監測儀表或攝錄影監視系統者，得提出替代之方法，報經直轄市、縣（市）主管機關同意後為之。營建工程空氣污染防制設施管理辦法第19條亦有相同規定，惟其明定應為同等防制效率或功能之替代方法。",
 "What if premises cannot install the required facilities, instruments or surveillance?",
 ["An alternative method may be proposed, subject to the consent of the municipal or county competent authority","An alternative may be adopted and recorded on file, with no need to seek the competent authority's consent","Central approval must be obtained before an alternative may be used, as local authorities have no such power","No alternative is allowed; operations must stop until the prescribed facilities have actually been installed"],
 "Article 12; compare Article 19 of the construction regulations."),

(FD,"第13條",2,"逸散粒狀-例外",
 "公私場所堆置之物質經處理後不易散布粒狀物於空氣者，得不受哪些條文限制？",
 ["經報請直轄市、縣（市）主管機關同意者，不受第四條堆置設施及第十一條攝錄影監視系統規定之限制","經報請中央主管機關核准者，不受第五條輸送設施及第十條監測儀表規定之限制，但仍應設攝錄影系統","經公私場所自行認定並記錄者，不受第六條車輛運輸及第八條裸露區域規定之限制，無須報請機關同意","經環境檢驗測定機構出具證明者，不受本辦法全部規定之限制，並得免依本法第二十三條規定辦理"],"a",
 "第13條：公私場所堆置之物質處理後不易散布粒狀物於空氣，並報經直轄市、縣（市）主管機關同意者，不受第4條及第11條規定限制。第4條為堆置逸散性粒狀污染物質應採行之防制設施規定，第11條為附表一序號一至七適用對象應設置攝錄影監視系統之規定。",
 "Which requirements may be waived where stored material hardly disperses after treatment?",
 ["With the consent of the municipal or county authority, the stockpiling controls in Article 4 and the video surveillance in Article 11","With central approval, the conveying controls in Article 5 and the monitoring instruments in Article 10, though surveillance is still required","On the premises' own assessment and record, the vehicle rules in Article 6 and the exposed area rules in Article 8, with no consent needed","With a certificate from a testing organization, every provision of these Regulations and also Article 23 of the Act itself"],
 "Article 13."),

(FD,"第14條",3,"逸散粒狀-施行日",
 "固定污染源逸散性粒狀污染物空氣污染防制設施管理辦法之施行日期規定為何？",
 ["除第七條第二項及第九條第三項自發布後三年施行外，自發布後一年施行","除第四條第三項及第十條第二項自發布後二年施行外，自發布後六個月施行","全部條文一律自發布日施行，並無任何條文另定緩衝期間或分階段施行","除罰則相關規定自發布後五年施行外，其餘條文均自發布後三年施行"],"a",
 "第14條：本辦法除第七條第二項及第九條第三項自發布後三年施行外，自發布後一年施行。第7條第2項為附表一序號四及十五採局部集氣系統者集氣效率應達百分之六十以上之規定，第9條第3項為道路交通島及人行道裸露區域覆土高度不得超過緣石上緣之規定，二者均給予三年之調適期間。",
 "When do the fugitive particulate control regulations take effect?",
 ["One year after promulgation, except Article 7(2) and Article 9(3), which take effect three years after promulgation","Six months after promulgation, except Article 4(3) and Article 10(2), which take effect two years after promulgation","All provisions take effect on the date of promulgation, with no grace period or phased commencement at all","Three years after promulgation for all provisions, except the penalty related ones which take effect after five years"],
 "Article 14."),
]
